#ifndef MODEL_PCEN_H
#define MODEL_PCEN_H

/* Generated by export_pcen.py from a trained LearnablePCEN (test-audiomoth-cnn/
 * student_model.py) - one value per STFT frequency bin (MODEL_PCEN_NUMBER_OF_BINS,
 * must equal main.c's STFT_NUMBER_OF_BINS), consumed by main.c's
 * STFT_NORMALIZATION_PCEN (see stftFastPow/computeSpectrogram there). Regenerate this
 * file (do not hand-edit) whenever the underlying checkpoint changes - do not mix
 * pcen.h/pcen.c from one checkpoint with model.h/model.c from another. */

#define MODEL_PCEN_NUMBER_OF_BINS 129
#define MODEL_PCEN_EPS 1.0000000000e-06f

/* (M+eps)^alpha exponent, per bin */
extern const float model_pcen_alpha[129];

/* added before the final pow, per bin (used raw, not just via delta_pow_r) */
extern const float model_pcen_delta[129];

/* final compression exponent, per bin */
extern const float model_pcen_r[129];

/* M's own causal-EMA smoothing rate, per bin */
extern const float model_pcen_ema_alpha[129];

/* delta**r, precomputed here rather than every frame on-device (constant per bin - see stftFastPow) */
extern const float model_pcen_delta_pow_r[129];

/* nominal M seed at the start of a recording (mean training-set power per bin - see compute_initial_m()) */
extern const float model_pcen_initial_m[129];

#endif
